### Key Features
1.  **Full Width (`full`)**: Takes up the full width of the parent with a small gap for the edges.
2.  **Centered (`center`)**: Constrains the content with a maximum width (usually `1280px`), centered horizontally on the screen.
3.  **Responsive**: It handles padding adjustments for mobile vs. desktop automatically.
4.  **Extensible**: It accepts `className` and `style` props so you can add custom background colors or flexbox settings.

### The Component

```jsx
import React from 'react';

/**
 * Layout Component
 * @param {Object} props
 * @param {'full' | 'center'} props.variant - Controls the layout constraint
 * @param {React.ReactNode} props.children - The content to be rendered
 * @param {string} props.className - Additional Tailwind classes
 * @param {string} props.background - Background color class (optional)
 * @param {string} props.padding - Padding size (optional)
 */
export default function Layout({ 
  variant = 'full', 
  children, 
  className = '', 
  background = 'bg-white', 
  padding = 'px-4 sm:px-6 lg:px-8',
  ...props 
}) {
  return (
    // Main Wrapper: Handles the height and background
    <div 
      className={`min-h-screen ${background} ${className}`} 
      {...props}
    >
      {/* Content Wrapper: Handles the variant (width constraint) */}
      <div 
        className={`
          mx-auto 
          ${variant === 'full' ? 'w-full max-w-full' : 'max-w-7xl'} 
          ${padding}
          flex flex-col min-h-full
        `}
      >
        {children}
      </div>
    </div>
  );
}
```

